import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { SettingsPageTemplate } from "../SettingsPageTemplate";
import { DeleteTrash } from "@rapid7/icons-material";
import { SettingsNavigation } from "../subcomponents/SettingsNavigation";
const navConfig = [
    {
        header: "Nav Section 1",
        items: [
            {
                description: "Item 1 description",
                id: "item-1",
                slots: {
                    leftIcon: _jsx(DeleteTrash, {}),
                    rightValue: "hello",
                },
                title: "Item 1",
                to: "/item-1",
            },
        ],
    },
    {
        header: "Nav Section 2",
        items: [
            {
                id: "item-2",
                title: "Item 2",
                to: "/item-2",
            },
        ],
    },
];
describe("SettingsPageTemplate", () => {
    it("Should render the nav correctly when using SettingsNav", () => {
        const { getByText, getByTestId } = render(_jsx(SettingsPageTemplate, { slots: {
                Navigation: () => _jsx(SettingsNavigation, { navConfig: navConfig }),
            } }));
        expect(getByText("Nav Section 1")).toBeInTheDocument();
        expect(getByText("Nav Section 2")).toBeInTheDocument();
        expect(getByText("Item 1")).toBeInTheDocument();
        expect(getByText("Item 1 description")).toBeInTheDocument();
        expect(getByTestId("DeleteTrashIcon")).toBeInTheDocument();
        expect(getByText("hello")).toBeInTheDocument();
        expect(getByText("Item 2")).toBeInTheDocument();
    });
    it("Should render components passed into slots", () => {
        const { getByText } = render(_jsx(SettingsPageTemplate, { slots: {
                Content: () => _jsx("div", { children: "I am content!" }),
                Navigation: () => _jsx("div", { children: "I am nav!" }),
            } }));
        expect(getByText("I am content!")).toBeInTheDocument();
        expect(getByText("I am nav!")).toBeInTheDocument();
    });
    it("Should render components passed as children", () => {
        const { getByText } = render(_jsx(SettingsPageTemplate, { slots: {
                Navigation: () => _jsx("div", { children: "I am nav!" }),
            }, children: _jsx("div", { children: "I am content!" }) }));
        expect(getByText("I am content!")).toBeInTheDocument();
        expect(getByText("I am nav!")).toBeInTheDocument();
    });
});
describe("SettingsNavigation", () => {
    it("Should highlight the selected item in the builtin nav when selected is true", async () => {
        const { getByText } = render(_jsx(SettingsNavigation, { navConfig: navConfig, selectedId: "item-2" }));
        const item1 = getByText("Item 1");
        const item2 = getByText("Item 2");
        const user = userEvent.setup();
        await user.click(item2);
        userEvent.click(item2);
        expect(item2.parentElement?.parentElement).toHaveClass("Mui-selected");
        expect(item1.parentElement?.parentElement).not.toHaveClass("Mui-selected");
    });
});
